package org.apache.commons.math.distribution;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.exception.NotStrictlyPositiveException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.special.Erf;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math3.exception.MathException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for NormalDistributionImpl#cumulativeProbability
 */
public class NormalDistributionImpl_cumulativeProbability_TriageGen1Test {

    private static final double DELTA = 1e-9;

    @Test
    public void testCumulativeProbability_FarLeftTail() throws MathException {
        double mean = 0.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);

        // dev = -41.0, which is < -40 * sd
        double x = -41.0;
        double result = dist.cumulativeProbability(x);

        Assert.assertEquals(0.0d, result, DELTA);
    }

    @Test
    public void testCumulativeProbability_FarRightTail() throws MathException {
        double mean = 10.0;
        double sd = 2.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);

        // dev = 100 - 10 = 90. 40 * sd = 80. 90 > 80.
        double x = 100.0;
        double result = dist.cumulativeProbability(x);

        Assert.assertEquals(1.0d, result, DELTA);
    }

    @Test
    public void testCumulativeProbability_AtMean() throws MathException {
        double mean = 5.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);

        // dev = 0. 0 is within 40 * sd.
        // Erf(0) = 0. Result = 0.5 * (1 + 0) = 0.5
        double x = 5.0;
        double result = dist.cumulativeProbability(x);

        Assert.assertEquals(0.5d, result, DELTA);
    }

    @Test
    public void testCumulativeProbability_StandardNormalOneSigma() throws MathException {
        double mean = 0.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);

        // x = 1.0. dev = 1.0.
        // Note: The implementation uses (dev) % (sd * sqrt(2)). 
        // This is a specific behavior of this implementation.
        double x = 1.0;
        double result = dist.cumulativeProbability(x);

        // Expected calculation based on the provided code logic:
        // dev = 1.0
        // limit = 1.0 * sqrt(2) approx 1.414
        // mod = 1.0 % 1.414 = 1.0
        // result = 0.5 * (1.0 + erf(1.0 / (1.0 * sqrt(2)))) is NOT what the code does.
        // The code does: 0.5 * (1.0 + Erf.erf( (dev) % (sd * sqrt(2)) ))
        // This looks like a potential bug in the source code provided (missing division), 
        // but we test against the provided logic.

        double expectedMod = 1.0 % (1.0 * Math.sqrt(2.0));
        double expected = 0.5 * (1.0 + org.apache.commons.math3.special.Erf.erf(expectedMod));

        Assert.assertEquals(expected, result, DELTA);
    }

    @Test
    public void testCumulativeProbability_BoundaryCondition() throws MathException {
        double mean = 0.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);

        // Exact boundary: dev = 40.0
        double x = 40.0;
        double result = dist.cumulativeProbability(x);

        // Since abs(40) is not > 40, it enters the erf calculation
        double expectedMod = 40.0 % (1.0 * Math.sqrt(2.0));
        double expected = 0.5 * (1.0 + org.apache.commons.math3.special.Erf.erf(expectedMod));

        Assert.assertEquals(expected, result, DELTA);
    }

    @Test
    public void testCumulativeProbability_NegativeDevWithinRange() throws MathException {
        double mean = 0.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);

        // dev = -1.0. abs(-1) < 40.
        double x = -1.0;
        double result = dist.cumulativeProbability(x);

        // mod = -1.0 % 1.414... In Java, % preserves sign. Result is -1.0
        double expectedMod = -1.0 % (1.0 * Math.sqrt(2.0));
        double expected = 0.5 * (1.0 + org.apache.commons.math3.special.Erf.erf(expectedMod));

        Assert.assertEquals(expected, result, DELTA);
    }
}
